<section x-show="citationSource" x-cloak x-ref="citationPanel" :id="$id('assistant-citation-panel')" data-assistant-citation-panel role="dialog" aria-label="Source details" tabindex="-1" @keydown.escape.stop.prevent="closeCitation()" class="relative my-3 min-w-0 rounded-lg border border-red-200 bg-red-50/60 p-4 text-sm text-stone-800 focus:outline-none focus-visible:ring-2 focus-visible:ring-red-500 dark:border-red-900 dark:bg-red-950/20 dark:text-stone-200">
    <div class="flex items-start justify-between gap-3">
        <div class="min-w-0">
            <p x-show="citationSource?.reference && citationSource.reference !== citationSource.title && !/^\[?ATHENA\s+\d+\]?$/i.test(citationSource.reference)" class="text-xs font-semibold text-red-900 dark:text-red-200" x-text="citationSource?.reference || ''"></p>
            <h3 class="mt-1 break-words font-semibold leading-6 text-stone-950 dark:text-stone-100" x-text="citationSource?.title || 'Reference material'"></h3>
            <p x-show="citationLocation(citationSource)" class="mt-1 break-words text-xs leading-5 text-stone-500 dark:text-stone-400" x-text="citationLocation(citationSource)"></p>
        </div>
        <button type="button" @click="closeCitation()" class="-mr-2 -mt-2 inline-flex h-11 w-11 shrink-0 items-center justify-center rounded-md text-stone-500 hover:bg-red-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-500 dark:text-stone-400 dark:hover:bg-red-950" aria-label="Close source details"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path stroke-linecap="round" d="m6 6 12 12M18 6 6 18" /></svg></button>
    </div>
    <p x-show="citationSource?.excerpt" class="mt-3 text-xs font-medium text-stone-500 dark:text-stone-400">Retrieved excerpt</p>
    <blockquote x-show="citationSource?.excerpt" class="mt-2 max-h-60 overflow-y-auto whitespace-pre-wrap break-words border-l-2 border-red-300 pl-3 leading-6 dark:border-red-800" x-text="citationSource?.excerpt"></blockquote>
    <p x-show="!citationSource?.excerpt" class="mt-3 leading-6 text-stone-500 dark:text-stone-400">No excerpt was saved with this reference.<span x-show="$store.researchAssistant.sourceUrl(citationSource)"> Open the source to check the supporting text.</span></p>
    <div class="mt-3 flex flex-wrap gap-2">
        <button x-show="canPreviewCitation(citationSource)" type="button" @click="$store.researchAssistant.openSourcePreview(citationSource, $event)" class="inline-flex min-h-11 items-center gap-2 rounded-md bg-red-900 px-3 py-2 text-xs font-semibold text-white hover:bg-red-950 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-500" aria-haspopup="dialog"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z" /><circle cx="12" cy="12" r="3" /></svg>Preview source</button>
        <a x-show="!canPreviewCitation(citationSource) && $store.researchAssistant.sourceUrl(citationSource)" :href="$store.researchAssistant.sourceUrl(citationSource) || null" target="_blank" rel="noopener noreferrer" class="inline-flex min-h-11 items-center gap-2 rounded-md border border-red-200 px-3 py-2 text-xs font-semibold text-red-900 hover:bg-red-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-500 dark:border-red-900 dark:text-red-200 dark:hover:bg-red-950">Open source<svg class="h-3.5 w-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="M14 3h7v7m0-7L10 14M10 4H5a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2h13a2 2 0 0 0 2-2v-5" /></svg></a>
    </div>
</section>
